// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0);
        vm.assume(amount <= address(this).balance);
        address user = address(0xE5f27b70946a160C61485d5a09f3F02c31fbF2FE);
        vm.deal(user, amount);
        vm.prank(user);
        c.addToBalance{value: amount}();
        vm.prank(user);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("withdrawBalance()"));
        uint256 balanceAfter = c.getBalance(user);
        assertTrue(balanceAfter == 0);
    }
}
